string day = "Wednesday";
string dayType;

switch (day)
{
    case "Monday":
    case "Tuesday":
    case "Wednesday":
    case "Thursday":
    case "Friday":
        dayType = "Weekday";
        break; // breaks out of the entire switch

    case "Saturday":
    case "Sunday":
        dayType = "Weekend";
        break;

    default:
        dayType = "Unknown day";
        break;
}

Console.WriteLine($"{day} is a {dayType}");
// Output: Wednesday is a Weekday

string day = "Saturday";

// Switch expression replaces the entire if-else or switch statement
string dayType = day switch
{
    "Monday" or "Tuesday" or "Wednesday" or "Thursday" or "Friday" => "Weekday",
    "Saturday" or "Sunday" => "Weekend",
    _ => "Unknown day"
};

Console.WriteLine($"{day} is a {dayType}");
// Output: Saturday is a Weekend

// Switch expression as a method return
public string GetDayType(string day) => day switch
{
    "Monday" or "Tuesday" or "Wednesday" or "Thursday" or "Friday" => "Weekday",
    "Saturday" or "Sunday" => "Weekend",
    _ => throw new ArgumentException("Invalid day name", nameof(day))
};

// Relational patterns with numeric ranges
string DescribeTemperature(int temp) => temp switch
{
    < 0 => "Freezing",
    >= 0 and < 15 => "Cold",
    >= 15 and < 25 => "Mild",
    >= 25 and < 35 => "Warm",
    >= 35 => "Hot",
    _ => "Invalid"
};

Console.WriteLine(DescribeTemperature(10));  // Cold
Console.WriteLine(DescribeTemperature(22));  // Mild
Console.WriteLine(DescribeTemperature(40));  // Hot

// Logical patterns with 'not'
string ValidateInput(string? input) => input switch
{
    not null and not "" => $"Received: {input}",
    null => "Input was null",
    "" => "Input was empty",
    _ => "Unexpected input"
};

// Type pattern matching with objects
object obj = 42;
string description = obj switch
{
    int i => $"Integer: {i}",
    string s => $"String of length {s.Length}",
    bool b => $"Boolean: {b}",
    null => "Null object",
    _ => $"Unknown type: {obj.GetType().Name}"
};
Console.WriteLine(description); // Integer: 42

public record Person(string Name, int Age);

Person person = new Person("Alice", 30);

// Property pattern: match on object properties
string category = person switch
{
    { Age: < 13 } => "Child",
    { Age: >= 13 and < 20 } => "Teenager",
    { Age: >= 20 and < 65 } => "Adult",
    { Age: >= 65 } => "Senior",
    _ => "Unknown"
};
Console.WriteLine(category); // Adult

// Positional pattern with tuple
(int x, int y) point = (5, 10);
string quadrant = point switch
{
    (0, 0) => "Origin",
    ( > 0, > 0) => "Quadrant I",
    ( < 0, > 0) => "Quadrant II",
    ( < 0, < 0) => "Quadrant III",
    ( > 0, < 0) => "Quadrant IV",
    (0, _) or (_, 0) => "On an axis",
    _ => "Unknown"
};
